RULES = [
 ("BR-01","Matching","A box matches a field by rule only when its label was approved before for that field in the same context (form section and whose fact)."),
 ("BR-02","Matching","A new field is created only when no existing field fits; near-duplicates block submission."),
 ("BR-03","Fields","Every field has one type, one validation, one whose-fact and one tier; validation starts from the form's own limits."),
 ("BR-04","Sections","A field belongs to one library section; forms keep their own section names and order for display only."),
 ("BR-05","Rules","Rules are written only in the condition language, over master fields; each rule stores its source and date checked."),
 ("BR-06","Rules","A rule applies once per application or to each person in a role; base forms are base for the principal only."),
 ("BR-07","Rules","Conditions that depend on an officer's judgement are never rules; they become agent requests."),
 ("BR-08","Questionnaires","The SQR asks only facts the client must give: not known, not supplied by a confirmed document, not staff-only."),
 ("BR-09","Review","A person reviews every new or uncertain item; a second person releases; the releaser never edits."),
 ("BR-10","Versioning","Every item has its own version inside a pathway version; a case pins the pathway version until a person adopts a new one."),
 ("BR-11","Change","A new edition re-enters review for changed boxes only; a government cut-off date makes adoption required."),
 ("BR-12","Facts","One current value per person per field; a newer verified value supersedes with history; a contradicting value raises a conflict."),
 ("BR-13","Duplicates","Email, phone and organisation name trigger a 'same person?' question; nothing is merged at capture."),
 ("BR-14","Rendering","Forms are filled by rules from confirmed facts only; AI never sets a form value at fill time."),
 ("BR-15","Outputs","The product never generates a barcode; a person validates barcode forms; a person submits, pays, signs and declares."),
 ("BR-16","Quality","No engine step goes live until it meets its agreed precision and recall on the test set."),
]

