NFRS = [
 ("NFR-01","Data residency","Client data stored in Canada; AI and OCR processing in Canada or the US only under no-training and zero-retention terms."),
 ("NFR-02","Traceability","Every configured item links to its source (file, page or box); every filled value links to its fact, source and confirmer."),
 ("NFR-03","Reproducibility","A filled form re-renders identically from its stamped form edition, map version and fact snapshot."),
 ("NFR-04","Determinism","Filling uses no AI; the same facts and versions always produce the same form."),
 ("NFR-05","AI governance","Each AI step has a typed output, versioned prompt, test set and score; it writes only to a draft; it can be switched off."),
 ("NFR-06","Security","Role-based access; the engine runs with the publisher's permissions; restricted fields masked by default."),
 ("NFR-07","Audit","Every release, rejection, conflict decision and form approval is logged with who and when."),
 ("NFR-08","Performance","Engine run for one combination completes within an agreed time; review screens load in under two seconds."),
 ("NFR-09","Resilience","If the AI is unavailable the engine stops cleanly; nothing half-built is published; manual entry is a recorded exception."),
 ("NFR-10","Accessibility","Client portal and review screens meet WCAG 2.1 AA."),
]

